@startuml

class FurnitureLine {
  + Name
}

class Piece {
  + Reference
  + Type
  + SellingPrice
}

class Component {
  + Code
  + ManufacturingPrice
  + Type
}

class PieceComponent {
  + Quantity
}

class Store {
  + Address
  + FaxNumber
}

class Order {
  + OrderNumber
  + Date
}

FurnitureLine "1" *-- "1..*" Piece
Piece "1" -- "1..*" PieceComponent
PieceComponent "*" -- "1" Component
Store "1" -- "*" Order
Order "1" -- "1..*" PieceComponent

@enduml

